/*
 * Task 0.2 spike: verify m5ops workbegin/workend ROI markers are visible
 * in gem5 SE mode on this aarch64 host.
 *
 * Encoding (util/m5/src/abi/arm64/m5op.S): .long 0xff000110 | (func << 16)
 *   M5OP_WORK_BEGIN = 0x5a, M5OP_WORK_END = 0x5b (asm/generic/m5ops.h)
 * ABI (pseudo_inst.hh workbegin simcall, RegABI64): X0=workid, X1=threadid
 */
#include <stdio.h>
#include <stdint.h>

static inline void m5_workbegin(uint64_t workid, uint64_t tid) {
    register uint64_t x0 __asm__("x0") = workid;
    register uint64_t x1 __asm__("x1") = tid;
    __asm__ volatile(
        ".inst 0xff005a10\n"   /* 0xff000110 | (0x5a << 16) */
        : "+r"(x0)
        : "r"(x1)
        : "memory");
}
static inline void m5_workend(uint64_t workid, uint64_t tid) {
    register uint64_t x0 __asm__("x0") = workid;
    register uint64_t x1 __asm__("x1") = tid;
    __asm__ volatile(
        ".inst 0xff005b10\n"   /* 0xff000110 | (0x5b << 16) */
        : "+r"(x0)
        : "r"(x1)
        : "memory");
}

int main(void) {
    uint64_t acc = 0;
    printf("pre-roi\n");
    m5_workbegin(1, 0);
    for (int i = 0; i < 200000; i++)   /* enough cycles to see a window */
        acc += (uint64_t)i * 0x9E3779B97F4A7C15ULL;
    m5_workend(1, 0);
    printf("post-roi acc=%llu\n", (unsigned long long)acc);
    return 0;
}
