    "balanced": [
        "add x9, x10, x11", "eor x12, x13, x14", "mul x15, x16, x17",
        "sub x18, x19, x20", "and x21, x22, x23", "orr x24, x25, x26",
        "fadd d8, d9, d10", "fmul d11, d12, d13",
        "add x27, x28, x9", "mul x10, x11, x12", "eor x13, x14, x15",
        "fadd d14, d15, d16", "fmul d17, d18, d19",
    ],
    "fp-heavy": [
        "fadd d8, d9, d10", "fsub d11, d12, d13", "fmul d14, d15, d16",
        "fadd d17, d18, d19", "fmul d20, d21, d22", "fsub d23, d24, d25",
        "fadd d26, d27, d28", "fmul d9, d10, d11", "fadd d12, d13, d14",
