def sanitize_asm_line(line, lineno, allow_mem):
    """校验一条用户/生成指令：非空、无标号/伪指令/危险指令，返回 (ok, err)。"""
    s = line.split("#")[0].split("//")[0].strip()
    if not s or s.startswith((".")):
        return None, None  # 空行/注释/伪指令 → 跳过
    if ":" in s:
