__asm__ volatile (
{asm_body}
    : "+r"(x9),  "+r"(x10), "+r"(x11), "+r"(x12), "+r"(x13),
      "+r"(x14), "+r"(x15), "+r"(x16), "+r"(x17), "+r"(x18),
      "+r"(x19), "+r"(x20), "+r"(x21), "+r"(x22), "+r"(x23),
      "+r"(x24), "+r"(x25), "+r"(x26), "+r"(x27), "+r"(x28)
