    r[0]=x9;  r[1]=x10; r[2]=x11; r[3]=x12; r[4]=x13;
    r[5]=x14; r[6]=x15; r[7]=x16; r[8]=x17; r[9]=x18;
    r[10]=x19; r[11]=x20; r[12]=x21; r[13]=x22; r[14]=x23;
