# 指令池（Task 7.2 随机基线 + Task 6.2 盲变异共用）。每条 = (asm 文本, op 类)
# 全部为 X 寄存器纯算术/逻辑/乘法指令：确定性、无隐式写 RAX 类副作用
#（x86 MUL quirk 的 ARM64 对应物 MUL Xd,Xn,Xm 是三操作数，无隐式目标）。
INST_POOL = {
