    ],
}

# 内存指令用 %[base] 引用 mem 数组（ asm 内 base 操作数注入 ）
MEM_ASM = "ldr x9, [%[base], #0]"


def sanitize_asm_line(line, lineno, allow_mem):
    """校验一条用户/生成指令：非空、无标号/伪指令/危险指令，返回 (ok, err)。"""
    s = line.split("#")[0].split("//")[0].strip()
    if not s or s.startswith((".")):
        return None, None  # 空行/注释/伪指令 → 跳过
    if ":" in s:
        return False, f"line {lineno}: labels unsupported ('{line}')"
    if not allow_mem and ("ldr" in s or "str" in s or "[" in s):
        return False, f"line {lineno}: memory ops need --allow-mem ('{line}')"
    # 白名单助记符前缀（防伪指令/分支/system 类破坏确定性）
    OK = ("add ", "sub ", "eor ", "and ", "orr ", "bic ", "mul ", "neg ",
          "fadd ", "fsub ", "fmul ", "fneg ", "fabs ", "ldr ", "str ",
          "movk ", "mov ", "madd ", "mneg ")
    if not any(s.startswith(p) for p in OK):
