def gen_random_sequence(n, mix, rng):
    pool = list(INST_POOL[mix])
    if mix == "mem" or mix == "balanced":
        # mem 指令含 %[base]，需要专门展开
        return None  # 由 build_asm_body 处理，见下
    return [pool[rng.randrange(len(pool))] for _ in range(n)]


def build_asm_body(lines, allow_mem, mem_bytes, base_comment):
    """把指令行列表变成 inline asm body 字符串。

    内存指令特殊处理：%[base] 出现在行内时，该行需要放到独立的
    __asm__ volatile 块里并传入 "r"(mem) 操作数（C 数组首地址）。
    为保持单一大块（保序），我们用 [base] 约束一次注入：
    所有 %[base] 在同一条 asm 里，gem5 只看指令流，C 约束无运行时差异。
    """
    if not allow_mem:
        body = "\n".join(f'    "{l}   \\n\\t"' for l in lines)
        return body, False
    # 含内存指令：把 %[base] 全部替换为 x8（在 asm 前把 mem 地址 mov 到 x8）
    has_mem = any("%[base]" in l or "[" in l for l in lines)
    if not has_mem:
        body = "\n".join(f'    "{l}   \\n\\t"' for l in lines)
        return body, False
    fixed = []
    for l in lines:
        fixed.append(l.replace("%[base]", "x8"))
    parts = [
        f'    "mov x8, %[base]   \\n\\t"  /* {base_comment}: mem base */',
    ]
    parts += [f'    "{l}   \\n\\t"' for l in fixed]
    # 覆盖 x8：asm 的 clobber 列表在模板里统一是 "+r"(x9..x28) + memory，
    # x8 是caller-saved且不再后续使用 → 只需声明 clobber。为简单起见
    # 在输出操作数追加 x8（+r），由调用方在 epilogue 前丢弃。
    return "\n".join(parts), True


def wrap_and_compile(seq_lines, out_path, seq_name, allow_mem, mem_bytes,
                     iters=1, keep_c=False):
    """生成 wrapper C 并编译为静态 ELF。返回 (elf_path, c_path) 。"""
    body, uses_x8 = build_asm_body(seq_lines, allow_mem, mem_bytes,
                                   "32KB region base")
    # x8 作为输出操作数（若内存指令使用），追加到约束列表
    out_ops = ('    : "+r"(x8), ' if uses_x8 else '    : ')
    # 重新组装模板里的 asm 块（在 body 前插入输出操作数行已由模板固定，
    # 因此这里直接把 uses_x8 信息编码进 body：见 WRAPPER_TEMPLATE 的 : "+r"(x9)...
    # —— 简化：x8 直接加入 clobber 文本）
    if uses_x8:
        body += '\n    : "x8"  /* mem base, clobbered */'
        # 模板 asm 的输出操作数行是固定的；x8 通过第二个冒号后的 clobber
        # 声明即可（x8 无需回读）。
        # 但模板把 clobber 写死为 "memory"，需要在 body 末尾替换。
        # 见下方 hack：我们生成的 body 自带完整 clobber 行。
        pass

    src = WRAPPER_TEMPLATE.format(
        seq_name=seq_name, n_lines=len(seq_lines), n_inst=len(seq_lines) * iters,
        mem_bytes=mem_bytes, iters=iters, wb=M5_WORKBEGIN, we=M5_WORKEND,
        asm_body=body,
    )
    if uses_x8:
        # 模板的 asm 语句以 : "memory"); 结尾；当 body 自带 clobber 行时，
        # 需要把模板的 "memory" 换成 "memory", x8 —— 直接文本替换生成的 src
        src = src.replace(': "memory"\n);', ': "memory", "x8"\n);')
        # 同时 %[base] 操作数必须作为输入传入：把 mem 数组地址注入
        src = src.replace(
            ': "memory", "x8"\n);',
            ': "memory", "x8"\n    : [base] "r" (mem)\n);')

    c_path = out_path + ".c"
    with open(c_path, "w") as f:
        f.write(src)
    r = subprocess.run(["gcc", "-static", "-O2", "-o", out_path, c_path],
                       capture_output=True, text=True, timeout=120)
    if r.returncode != 0:
        sys.exit(f"ERROR: gcc failed:\n{r.stderr}\n(wrapper kept at {c_path})")
    if not keep_c:
        pass  # 保留 .c 以便审查（与 sdc_probe_workload.c 仓库惯例一致）
    return out_path, c_path


def load_sequence(path):
    """从 .S/.txt 读指令序列（每行一条）。返回 (lines, errors)。"""
    lines, errors = [], []
    with open(path) as f:
        for i, raw in enumerate(f, 1):
            s, err = sanitize_asm_line(raw, i, allow_mem=True)
            if err:
                errors.append(err)
            elif s:
                lines.append(s)
    return lines, errors


def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("--seq", help="输入：.S/.txt 指令序列 或 现成 ELF")
    ap.add_argument("--pass-through", action="store_true",
                    help="--seq 是现成 aarch64 ELF：直接验证并复制到 --out")
    ap.add_argument("--out", required=True, help="输出 ELF 路径")
    ap.add_argument("--random", action="store_true",
                    help="生成随机序列（Task 7.2 基线，论文 Generator 第 0 代）")
    ap.add_argument("--n-inst", type=int, default=1000,
                    help="随机序列指令数（默认 1000；论文 IRF=10K/FU=5K/L1D=30K）")
    ap.add_argument("--mix", default="int-heavy",
                    choices=list(INST_POOL.keys()),
                    help="随机序列指令池（默认 int-heavy）")
    ap.add_argument("--seed", type=int, default=20260916,
                    help="随机序列种子（确定性要求）")
    ap.add_argument("--allow-mem", action="store_true",
                    help="序列含 ldr/str（base=x8 指向 32KB 区域）")
    ap.add_argument("--mem-bytes", type=int, default=32 * 1024,
                    help="内存区域大小（默认 32KB=L1D 容量，论文 L1D 协议）")
    ap.add_argument("--iters", type=int, default=1,
                    help="核心序列循环次数（ROI 内重复执行）")
    ap.add_argument("--keep-c", action="store_true", default=True,
                    help="保留生成的 .c（默认保留，仓库惯例）")
    args = ap.parse_args()

    if not args.seq and not args.random:
        ap.error("需要 --seq 或 --random 之一")

    if args.pass_through:
        if not args.seq or not os.path.isfile(args.seq):
            sys.exit("ERROR: --pass-through 需要存在的 --seq ELF")
        out = args.out
        if os.path.isdir(out):
            out = os.path.join(out, os.path.basename(args.seq))
        subprocess.run(["cp", args.seq, out], check=True)
        r = subprocess.run(["file", out], capture_output=True, text=True)
        print(f"pass-through: {r.stdout.strip()}")
        print(f"ELF: {out}")
        return 0

    if args.random:
        import random as _r
        rng = _r.Random(args.seed)
        if args.mix == "mem":
            # mem 池：固定 stride-8 扫 32KB 区域（论文 L1D 协议），
            # n-inst 条从池中均匀抽取
            pool = INST_POOL["mem"]
            lines = [pool[rng.randrange(len(pool))] for _ in range(args.n_inst)]
            args.allow_mem = True
        elif args.mix == "balanced":
            lines = []
            for _ in range(args.n_inst):
                # balanced = int/fp/mem 混合：60% int, 25% fp, 15% mem
                u = rng.random()
                if u < 0.60:
                    p = INST_POOL["int-heavy"]
                elif u < 0.85:
                    p = INST_POOL["fp-heavy"]
                else:
                    p = INST_POOL["mem"]
                    args.allow_mem = True
                lines.append(p[rng.randrange(len(p))])
        else:
            pool = INST_POOL[args.mix]
            lines = [pool[rng.randrange(len(pool))] for _ in range(args.n_inst)]
        seq_name = f"random-{args.mix}-n{args.n_inst}-s{args.seed}"
    else:
        lines, errors = load_sequence(args.seq)
        if errors:
            print("ERROR: sequence sanitization failed:", file=sys.stderr)
            for e in errors:
                print("  " + e, file=sys.stderr)
            return 1
        if not lines:
            sys.exit("ERROR: empty sequence")
        seq_name = os.path.basename(args.seq)

    if args.allow_mem and args.mem_bytes < 64:
        sys.exit("ERROR: --mem-bytes too small")

    elf, c = wrap_and_compile(lines, args.out, seq_name, args.allow_mem,
                              args.mem_bytes, args.iters)
    r = subprocess.run(["file", elf], capture_output=True, text=True)
    print(f"wrapped {len(lines)} lines (iters={args.iters}) -> {elf}")
    print(f"  {r.stdout.strip()}")
    print(f"  wrapper C: {c}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

