    const unsigned n_int  = cpu->physRegFile().numPhysicalIntRegs;
    const unsigned n_flt  = cpu->physRegFile().numPhysicalFloatRegs;
    irf_state[0].assign(n_int, PrfRegState{});
    irf_state[1].assign(n_flt, PrfRegState{});
