/*
 * CHAOSFUPerm — FU permanent fault injector, execution level (Task 5.2).
 * See CHAOSFUPerm.py for the fault-model contract. Hooked from
 * cpu/o3/iew.cc writebackInsts (guarded call, zero cost when unmounted):
 * every executed instruction of the target OpClass gets its result
 * corrupted via DynInst::corruptResultRegVal — the writeback-path
 * equivalent of a stuck gate affecting every use, i.e. permanent.
 */
#ifndef __CHAOS_FU_PERM_CHAOSFUPERM_HH__
#define __CHAOS_FU_PERM_CHAOSFUPERM_HH__

#include "sim/sim_object.hh"
#include "base/output.hh"
#include "base/statistics.hh"
#include "base/types.hh"

#include <cstdint>

namespace gem5
{

class CHAOSFUPermParams;
namespace o3 { class CPU; }

class CHAOSFUPerm : public SimObject
{
  public:
    CHAOSFUPerm(const CHAOSFUPermParams &p);
    ~CHAOSFUPerm() override;

    // Single active instance (the iew.cc guard consults this + the hook).
    static CHAOSFUPerm *instance;

    // Called from IEW::writebackInsts per completing instruction.
    // Returns true if the instruction's result was corrupted.
    bool onWriteback(class o3::DynInstPtr inst);

  private:
    o3::CPU *cpu;
    int target_opclass;      // enums::OpClass value (-1 = none)
    uint64_t fault_mask;
    bool write_log;
    OutputStream *log_stream = nullptr;

  protected:
    struct Stats : public statistics::Group
    {
        Stats(statistics::Group *parent);
        statistics::Scalar numCorrupted;
        statistics::Scalar numMatchedOpClass;
    } stats;
};

// Guard + hook used by cpu/o3/iew.cc (defined in CHAOSFUPerm.cc).
extern bool fu_perm_enabled;
void fu_perm_on_writeback(class o3::DynInstPtr inst);

} // namespace gem5

#endif // __CHAOS_FU_PERM_CHAOSFUPERM_HH__

