#include "CHAOSFUPerm/CHAOSFUPerm.hh"
#include "params/CHAOSFUPerm.hh"
#include "cpu/o3/cpu.hh"
#include "cpu/o3/dyn_inst.hh"
#include "cpu/o3/dyn_inst_ptr.hh"
