        // overload; symmetric hook so SIMD FP is covered too).
        if (cpu->chaosFPUHook) {
            cpu->chaosFPUHook->maybeCorruptWritebackBlob(reg, val);
        }
        cpu->setReg(reg, val, threadNumber);
        setResult(reg->regClass(), val);
