    if (n == "IntAlu")
        synthesizeAdder(64);
    else if (n == "IntMult")
        synthesizeMultiplier(64);
    else
        throw std::runtime_error(
            "CHAOSGateFU: netlist available for IntAlu | IntMult (got '"
            + n + "'; FP netlists are Task 5.4)");

