                int pg = p[i-d].back(), gg = g[i-d].back();
                int pand = synthGate(AND, pv, gg);
                int gor  = synthGate(OR, gv, pand);
                int pandp = synthGate(AND, pv, pg);
                np[i] = pandp; ng[i] = gor;
            } else { np[i] = pv; ng[i] = gv; }
        }
        for (int i = 0; i < width; i++) { p[i].push_back(np[i]); g[i].push_back(ng[i]); }
    }
    for (int i = 0; i < width; i++) {
        if (i == 0) po_gates.push_back(p[0].back());
        else po_gates.push_back(synthGate(XOR, p[i].back(), g[i-1].back()));
    }
    po_gates.push_back(g[width-1].back());
}

void synthesizeMultiplier(int width) {
    gates.clear(); po_gates.clear(); pi_width = 2 * width;
    auto PI = [&](int idx) { return -(idx + 1); };
    vector<vector<int>> pp(width, vector<int>(width));
    for (int i = 0; i < width; i++)
        for (int j = 0; j < width; j++)
            pp[i][j] = synthGate(AND, PI(j), PI(width + i));
    int not_a0 = synthGate(NOT, PI(0), PI(0));
    int const0 = synthGate(AND, PI(0), not_a0);
    vector<int> acc(2 * width, const0);
    for (int j = 0; j < width; j++) acc[j] = pp[0][j];
    for (int i = 1; i < width; i++) {
        vector<int> sum(2 * width);
        int carry = const0;
        for (int k = 0; k < 2 * width; k++) {
            int x = acc[k];
            int j = k - i;
            int y = (0 <= j && j < width) ? pp[i][j] : const0;
            int xyc = synthGate(XOR, x, y);
            int xy  = synthGate(AND, x, y);
            sum[k] = synthGate(XOR, xyc, carry);
            int xc = synthGate(AND, xyc, carry);
            carry = synthGate(OR, xy, xc);
        }
        acc = sum;
    }
    for (int k = 0; k < 2 * width; k++) po_gates.push_back(acc[k]);
}

vector<bool> evalNet(const vector<bool> &pis) {
    vector<bool> val(gates.size());
    auto read = [&](int in) -> bool {
        if (in < 0) return pis[-in - 1];
        return val[in];
    };
    for (size_t gi = 0; gi < gates.size(); gi++) {
        const Gate &g = gates[gi];
        bool v;
        switch (g.type) {
          case AND: v = read(g.in0) && read(g.in1); break;
          case OR:  v = read(g.in0) || read(g.in1); break;
          case XOR: v = read(g.in0) != read(g.in1); break;
          case NOT: v = !read(g.in0); break;
          default: v = false;
        }
        val[gi] = v;
    }
    vector<bool> po(po_gates.size());
    for (size_t i = 0; i < po_gates.size(); i++)
        po[i] = val[po_gates[i]];
    return po;
}

int main() {
