22	// ---------------------------------------------------------------------------
23	// Netlist synthesis
24	// ---------------------------------------------------------------------------
25	// Helper adders on the flat gate list. PI encoding (pi_width = 2*w):
26	//   PI[i]        = a[i]   (i < w)
27	//   PI[w + j]    = b[j]
28	// Returns the gate index producing the sum/output bit.
29	
30	int
31	CHAOSGateFU::synthGate(GateType t, int in0, int in1)
32	{
33	    gates.push_back({t, in0, in1});
34	    return (int)gates.size() - 1;
35	}
36	
37	// Kogge-Stone prefix adder: standard sparse structure.
38	//   p[i] = a XOR b, g[i] = a AND b  (preprocess)
39	//   prefix: (g,p) o (G,P) = (g OR (p AND G), p AND P)
40	//   sum[i] = p[i] XOR carry[i-1]; carry[i] = g-prefix[i]
41	void
42	CHAOSGateFU::synthesizeAdder(int width)
43	{
44	    gates.clear();
45	    po_gates.clear();
46	    pi_width = 2 * width;
47	    // bit slices of intermediates, indexed [level][bit]
48	    std::vector<std::vector<int>> p(width), g(width);
49	
50	    // Preprocess.
51	    for (int i = 0; i < width; i++) {
52	        int ai = -(i + 1);              // PI a[i]
53	        int bi = -(width + i + 1);      // PI b[i]
54	        p[i].push_back(synthGate(XOR, ai, bi));
55	        g[i].push_back(synthGate(AND, ai, bi));
56	    }
57	    // Prefix network (Kogge-Stone: distances 1,2,4,...).
58	    int level = 0;
59	    for (int d = 1; d < width; d <<= 1) {
60	        std::vector<int> np(width), ng(width);
61	        for (int i = 0; i < width; i++) {
62	            int pv = p[i].back(), gv = g[i].back();
63	            if (i - d >= 0) {
64	                int pg = p[i - d].back(), gg = g[i - d].back();
65	                int pand = synthGate(AND, pv, gg);      // p & G
66	                int gor  = synthGate(OR, gv, pand);      // g | (p & G)
67	                int pandp = synthGate(AND, pv, pg);      // p & P
68	                np[i] = pandp;
69	                ng[i] = gor;
70	            } else {
71	                np[i] = pv;
72	                ng[i] = gv;
73	            }
74	        }
75	        for (int i = 0; i < width; i++) {
76	            p[i].push_back(np[i]);
77	            g[i].push_back(ng[i]);
78	        }
79	        level++;
80	    }
81	    // Sum: sum[i] = p[i] XOR c[i-1], c[i-1] = g[i-1] (final prefix),
82	    // sum[0] = p[0]. Carry-out = g[width-1] (bit `width` of the PO).
83	    // sum[i] = p0[i] XOR carry[i-1]: p0 is the PREPROCESS propagate bit
84	    // (level 0), NOT the final prefix p — the standalone exhaustive tests
85	    // (W=4/8/12, 17M vectors) caught this.
86	    for (int i = 0; i < width; i++) {
87	        if (i == 0) {
88	            po_gates.push_back(p[0].front());
89	        } else {
90	            po_gates.push_back(synthGate(XOR, p[i].front(), g[i - 1].back()));
91	        }
92	    }
93	    // Carry-out as an extra PO (bit `width`); width+1 outputs total.
94	    po_gates.push_back(g[width - 1].back());
95	}
