98	// acc bits are represented as (gate_index, valid); a fresh AND-tied-to-0
99	// constant gate stands in for "bit is constant zero" so NO sentinel index
100	// is ever used (the earlier -1 sentinel collided with the PI encoding
101	// in0<0 -> PI, corrupting the netlist — equivalence test crashed).
102	// Structure: pp[i][j] = a[j] & b[i]; then 63 ripple adder rows
103	// accumulate (pp[i] << i). Each full adder is XOR/AND/OR primitives.
104	void
105	CHAOSGateFU::synthesizeMultiplier(int width)
106	{
107	    gates.clear();
108	    po_gates.clear();
109	    pi_width = 2 * width;
110	    auto PI = [&](int idx) { return -(idx + 1); };
111	
112	    // Partial products.
113	    std::vector<std::vector<int>> pp(width, std::vector<int>(width));
114	    for (int i = 0; i < width; i++)
115	        for (int j = 0; j < width; j++)
116	            pp[i][j] = synthGate(AND, PI(j), PI(width + i));
117	
118	    // Constant-zero gate: a[0] AND NOT a[0].
119	    int not_a0 = synthGate(NOT, PI(0), PI(0));
120	    int const0 = synthGate(AND, PI(0), not_a0);
121	
122	    // Initial accumulator: row 0 (value = pp[0] << 0), 2w bits.
123	    std::vector<int> acc(2 * width, const0);
124	    for (int j = 0; j < width; j++)
125	        acc[j] = pp[0][j];
126	
127	    // Ripple accumulation of rows 1..w-1.
128	    for (int i = 1; i < width; i++) {
129	        std::vector<int> sum(2 * width);
130	        int carry = const0;
131	        for (int k = 0; k < 2 * width; k++) {
132	            int x = acc[k];
133	            int j = k - i;                      // row contributes at bit k
134	            int y = (0 <= j && j < width) ? pp[i][j] : const0;
135	            int xyc = synthGate(XOR, x, y);       // x ^ y
136	            int xy  = synthGate(AND, x, y);       // x & y
137	            sum[k] = synthGate(XOR, xyc, carry);  // x ^ y ^ c
138	            int xc = synthGate(AND, xyc, carry);  // (x^y) & c
139	            carry = synthGate(OR, xy, xc);        // majority
140	        }
141	        acc = sum;
142	    }
143	    for (int k = 0; k < 2 * width; k++)
144	        po_gates.push_back(acc[k]);
145	}
